-- STEP03: bounded per-element alignment and independent font scale. Existing identities, workflow order and authorization are unchanged.
CREATE OR REPLACE FUNCTION ff_private.a07_valid_elements(v jsonb, p_screen text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE g record; e jsonb; seen text[]; allowed text[]; spec jsonb:='{"dashboard_status":{"screen":"dashboard","keys":["dashboard_status_tag"],"styleOnly":true},"orders_status":{"screen":"orders","keys":["orders_status_tag","orders_addition_warning"],"styleOnly":true},"driver_status":{"screen":"driver","keys":["driver_offer_countdown","driver_status_tag"],"styleOnly":true},"cashier_status":{"screen":"cashier","keys":["cashier_status_tag","cashier_addition_warning"],"styleOnly":true},"burger_regions":{"screen":"burger_kitchen","keys":["ffBurgerKitchenStatus","ffBurgerKitchenBranch","ffBurgerKitchenActive","ffBurgerKitchenFinished"],"styleOnly":true},"dashboard_regions":{"screen":"dashboard","keys":["ffx-hero-title","ffx-hero-sub","ffx-kpis","ffx-shortcuts","ffx-order-list","ffx-overdue"],"styleOnly":true},"order_fields":{"screen":"orders","keys":["newBranch","ffbQuickInput","newPhone","newArea","newFee","newNotes","newCustomerName","newChannel","newFullAddress","ffbMenuSearch","newItems"],"styleOnly":true},"order_tabs":{"screen":"orders","keys":["ffbTabMenu","ffbTabText"],"styleOnly":false},"order_tools":{"screen":"orders","keys":["ffbApplyText","ffbMenuReload"],"styleOnly":true},"cashier_regions":{"screen":"cashier","keys":["cashierOrders"],"styleOnly":true},"assembly_regions":{"screen":"assembly","keys":["ffV12BranchTitle","ffV12AssemblyStatus","ffV12AssemblySummary","ffV12AssemblyOrders"],"styleOnly":true},"catalog_fields":{"screen":"catalog","keys":["ff51CatName","ff51ItemName","ff51ItemPrice","ff51OfferName","ff51OfferPrice"],"styleOnly":true},"catalog_regions":{"screen":"catalog","keys":["ff51CatalogItems","ff51OffersList"],"styleOnly":true},"customer_fields":{"screen":"customers","keys":["ff51CustomerSearch","ff51CustomerNoteText"],"styleOnly":true},"customer_regions":{"screen":"customers","keys":["ff51CustomersList","ff51CustomerHistory","ff51CustomerNotesList"],"styleOnly":true},"report_fields":{"screen":"reports","keys":["ff76From","ff76To","ff76Branch","ff76Driver","ffA10Staff","ffA10Area","ffA10Item","ffA10Status","ff76Mode","ff76Trend"],"styleOnly":true},"report_regions":{"screen":"reports","keys":["ff76Status","ff76Body","ff76ApprovalBox"],"styleOnly":true},"staff_regions":{"screen":"staff","keys":["staffAdminList","staffAuditList"],"styleOnly":true},"archive_fields":{"screen":"archive","keys":["ff51ArchiveFrom","ff51ArchiveTo","ff51ArchiveStatus","ff51ArchiveBranch"],"styleOnly":true},"archive_regions":{"screen":"archive","keys":["ff51ArchiveCount","ff51ArchiveList"],"styleOnly":true},"ratings_regions":{"screen":"ratings","keys":["ff51RatingBranch","ff51RatingsList"],"styleOnly":true},"reservation_fields":{"screen":"reservations","keys":["ff49ReserveBranch","ff49ReserveName","ff49ReservePhone","ff49ReserveNotes","ff49ReservePickup","ff49ReserveItems"],"styleOnly":true},"reservation_regions":{"screen":"reservations","keys":["ff49ReservationsList"],"styleOnly":true},"case_fields":{"screen":"cases","keys":["ff41Kind","ff41Branch","ff41Priority","ff41Subject","ff41Description","ff41FilterKind","ff41FilterStatus"],"styleOnly":true},"case_regions":{"screen":"cases","keys":["ff41CaseList","ff41Detail"],"styleOnly":true},"message_fields":{"screen":"messages","keys":["ff39Title","ff39Role","ff39Branch","ff39Body"],"styleOnly":true},"message_regions":{"screen":"messages","keys":["ff39InboxList","ff39SentLog"],"styleOnly":true},"system_regions":{"screen":"system","keys":["ff48Summary","ff48Rows","ff47Stats","ff47Cases","ff46Summary","ff44Results","ff43Findings"],"styleOnly":true},"reports_actions":{"screen":"reports","keys":["ff76Run","ff76Preview","ff76Download","ff76Share"]},"dashboard_actions":{"screen":"dashboard","keys":["ffx-hero-new","ffx-hero-reserve","ffx-hero-overdue"]},"orders_actions":{"screen":"orders","keys":["createBtn","ffA06DiscardDraft","ffReserveBottom"]},"driver_actions":{"screen":"driver","keys":["ff51BreakBtn","clockInBtn","clockOutBtn"]},"assembly_actions":{"screen":"assembly","keys":["ffV12Toggle","ffV12Refresh","ffV12BurgerOpen","ffV12Logout"]},"burger_actions":{"screen":"burger_kitchen","keys":["ffBurgerKitchenNotifications","ffBurgerViewFinished","ffBurgerKitchenRefresh","ffBurgerKitchenLogout"]},"catalog_actions":{"screen":"catalog","keys":["ff51ItemSave","ff51ItemReset"]},"catalog_offers":{"screen":"catalog","keys":["ff51OfferSave","ff51OfferReset"]},"archive_actions":{"screen":"archive","keys":["ff51ArchiveRefresh","ff51ArchiveExport","ff51ArchiveClose"]},"ratings_actions":{"screen":"ratings","keys":["ff51RatingsRefresh","ff51RatingsClose"]},"reservations_actions":{"screen":"reservations","keys":["ff49ReservationsRefresh","ff49ReservationsClose"]},"cases_actions":{"screen":"cases","keys":["ff41Refresh","ff41Close"]},"messages_actions":{"screen":"messages","keys":["ff39Refresh","ff39Close"]},"system_actions":{"screen":"system","keys":["ff48Refresh","ff48Export","ff48Close"]},"driver_regions":{"screen":"driver","keys":["clockInBtn","driverOffers","driverTasks"]},"assembly_stats":{"screen":"assembly","keys":["ffV12CountAll","ffV12CountPrinted","ffV12CountPreparing","ffV12CountReady"]},"cashier_stage":{"screen":"cashier","keys":["cashier_stage"]},"staff_actions":{"screen":"staff","keys":["staffAuditRefresh"]},"customers_actions":{"screen":"customers","keys":["ff51CustomerFind","ff51CustomerNoteSave"]},"finance_actions":{"screen":"finance","keys":["ff42Load","ff42Export","ff42ClosePanel","ff42Save","ff42CloseSettlement","ff42ShowDetail"],"styleOnly":true},"finance_fields":{"screen":"finance","keys":["ff42Day","ff42Branch","ff42CashDue","ff42CashReceived","ff42Difference","ff42Notes"],"styleOnly":true},"finance_regions":{"screen":"finance","keys":["ff42Status","ff42Summary","ff42List","ff42Form","ff42Detail"],"styleOnly":true},"branches_actions":{"screen":"branches","keys":["ffA05BranchPolicyBtn","ffA05Close","ffA05SaveHours","ffA05SaveTariff","ffA05PriceHistory"],"styleOnly":true},"branches_fields":{"screen":"branches","keys":["ffA05PolicyBranch","ffA05Effective","ffA05Reason","ffA05Day","ffA05Closed","ffA05Open","ffA05CloseTime","ffA05Shift","ffA05Area","ffA05Tariff"],"styleOnly":true},"branches_regions":{"screen":"branches","keys":["ffA05PolicyStatus","ffA05PolicyCurrent","ffA05PolicyHistory","ffA05PriceRows"],"styleOnly":true},"login_actions":{"screen":"login","keys":["loginBtn","ff61ApplyToggle","ff61StatusToggle","ff71CustomerToggle","ff71CustomerSend","ff71CustomerVerify","ff61ApplySend","ff61TrackSend"],"styleOnly":true},"login_fields":{"screen":"login","keys":["email","password","ff71CustomerPhone","ff71CustomerCode","ff61TrackCode","loginStatus","ff71CustomerMessage"],"styleOnly":true},"join_fields":{"screen":"login","keys":["join_name","join_email","join_phone","join_qualification","join_address","join_age","join_marital","join_role","join_experience","join_message","ff61Consent","ff61ApplyInfo"],"styleOnly":true},"customer_portal_actions":{"screen":"customer_portal","keys":["ff28Refresh","ff28Logout"],"styleOnly":true},"customer_portal_regions":{"screen":"customer_portal","keys":["ff28Title","ff28State","ff28Rows","ff28Name","ff28Role"],"styleOnly":true},"system_qa_controls":{"screen":"system","keys":["ff47Reload","ff47Close","ff47Version","ff47Title","ff47Create","ff47Runs","ff47Export","ff47Finish","ff47Reopen","ff47Category","ff47Filter"],"styleOnly":true},"system_readiness_controls":{"screen":"system","keys":["ff46Run","ff46Export","ff46Close"],"styleOnly":true},"system_access_controls":{"screen":"system","keys":["ff45Run","ff45Export","ff45Close"],"styleOnly":true},"system_integrity_controls":{"screen":"system","keys":["ff44Export","ff44Close","ff44From","ff44To","ff44Run"],"styleOnly":true},"system_security_controls":{"screen":"system","keys":["ff43Run","ff43Export","ff43Close"],"styleOnly":true},"case_contact_controls":{"screen":"cases","keys":["ff41Order","ff41CustomerName","ff41CustomerPhone","ff41Channel","ff41Create"],"styleOnly":true},"message_delivery_controls":{"screen":"messages","keys":["ff39Send","ff39SentRefresh"],"styleOnly":true},"dashboard_alert_controls":{"screen":"dashboard","keys":["ff40AlertRefresh","ff40AlertsClose","ff40AlertBranch"],"styleOnly":true},"staff_filter_controls":{"screen":"staff","keys":["ffEditMyAccount","staffAdminRefresh","ffA05StaffSearch","ffA05StaffRole","ffA05StaffActive","ffA05StaffSort","permissionEmployee","permissionLoad"],"styleOnly":true},"catalog_edit_controls":{"screen":"catalog","keys":["ff51CatalogRefresh","ff51CatalogClose","ffCatalogCardTarget","ffCatalogCardSort","ffCatalogCardStyle","ffCatalogCardSave","ffAliasTarget","ffAliasNames","ffAliasSave","ffAliasDefault"],"styleOnly":true},"customer_close_control":{"screen":"customers","keys":["ff51CustomersClose"],"styleOnly":true},"archive_page_controls":{"screen":"archive","keys":["ff51ArchivePrev","ff51ArchiveNext"],"styleOnly":true},"order_change_controls":{"screen":"orders","keys":["ff50Refresh","ff50Close","ff50RequestItems","ff50RequestReason","ff50RequestSave","ff50RequestCancel"],"styleOnly":true},"order_transfer_controls":{"screen":"orders","keys":["ff49TransferRefresh","ff49TransferClose"],"styleOnly":true},"reservation_save_control":{"screen":"reservations","keys":["ff49ReserveSave"],"styleOnly":true},"assembly_sound_control":{"screen":"assembly","keys":["ff66AssemblySoundSettings"],"styleOnly":true},"staff_edit_controls":{"screen":"staff","keys":["ffEditClose","ffEditSave"],"styleOnly":true}}'::jsonb;
BEGIN
 IF v IS NULL OR jsonb_typeof(v)<>'object' THEN RETURN false; END IF;
 FOR g IN SELECT * FROM jsonb_each(v) LOOP
  IF NOT spec ? g.key OR (p_screen<>'all' AND spec->g.key->>'screen'<>p_screen) OR jsonb_typeof(g.value)<>'array' THEN RETURN false; END IF;
  SELECT array_agg(k) INTO allowed FROM jsonb_array_elements_text(spec->g.key->'keys') k;
  IF jsonb_array_length(g.value)<>cardinality(allowed) THEN RETURN false; END IF;
  IF coalesce((spec->g.key->>'styleOnly')::boolean,false) AND (SELECT array_agg(a.row->>'key' ORDER BY a.ord) FROM jsonb_array_elements(g.value) WITH ORDINALITY a(row,ord)) IS DISTINCT FROM allowed THEN RETURN false; END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(g.value) a WHERE a->>'orderMode'='inherit') NOT IN (0,cardinality(allowed)) THEN RETURN false; END IF;
  seen:='{}';
  FOR e IN SELECT * FROM jsonb_array_elements(g.value) LOOP
   IF jsonb_typeof(e)<>'object' THEN RETURN false; END IF;
   IF NOT (e ?& ARRAY['key','shape','size']) OR EXISTS(SELECT 1 FROM jsonb_object_keys(e) k WHERE k NOT IN ('key','shape','size','font','weight','spacing','border','shadow','tone','orderMode','icon','hover','press','align','textScale'))
      OR NOT coalesce(e->>'key'=ANY(allowed),false) OR coalesce(e->>'key'=ANY(seen),true)
      OR NOT coalesce(e->>'shape' IN ('inherit','pack','square','round','pill','outline','icon_label'),false)
      OR NOT coalesce(e->>'size' IN ('inherit','normal','large'),false) THEN RETURN false;END IF;
   IF EXISTS(SELECT 1 FROM jsonb_each(e) x WHERE x.key NOT IN ('key','shape','size') AND NOT CASE x.key
      WHEN 'orderMode' THEN x.value='"inherit"'::jsonb
      WHEN 'font' THEN x.value IN ('"system"'::jsonb,'"tahoma"'::jsonb,'"serif"'::jsonb,'"cairo"'::jsonb,'"noto"'::jsonb)
      WHEN 'align' THEN x.value IN ('"start"'::jsonb,'"center"'::jsonb,'"end"'::jsonb)
      WHEN 'textScale' THEN x.value IN ('"normal"'::jsonb,'"large"'::jsonb)
      WHEN 'weight' THEN x.value IN ('"normal"'::jsonb,'"strong"'::jsonb)
      WHEN 'spacing' THEN x.value IN ('"normal"'::jsonb,'"wide"'::jsonb)
      WHEN 'border' THEN x.value IN ('"thin"'::jsonb,'"strong"'::jsonb)
      WHEN 'shadow' THEN x.value IN ('"none"'::jsonb,'"soft"'::jsonb)
      WHEN 'icon' THEN x.value IN ('"none"'::jsonb,'"check"'::jsonb,'"arrow"'::jsonb,'"star"'::jsonb,'"search"'::jsonb,'"file"'::jsonb) AND e->>'key' IN ('ff76Run','ff76Preview','ff76Download','ff76Share','ffx-hero-new','ffx-hero-reserve','ff51ArchiveRefresh','ff51ArchiveExport','ff51CustomerFind')
      WHEN 'hover' THEN x.value IN ('"none"'::jsonb,'"outline"'::jsonb,'"shadow"'::jsonb) AND e->>'key' IN ('ff76Run','ff76Preview','ff76Download','ff76Share','ffx-hero-new','ffx-hero-reserve','ff51ArchiveRefresh','ff51ArchiveExport','ff51CustomerFind')
      WHEN 'press' THEN x.value IN ('"none"'::jsonb,'"inset"'::jsonb) AND e->>'key' IN ('ff76Run','ff76Preview','ff76Download','ff76Share','ffx-hero-new','ffx-hero-reserve','ff51ArchiveRefresh','ff51ArchiveExport','ff51CustomerFind')
      WHEN 'tone' THEN x.value IN ('"navy"'::jsonb,'"red"'::jsonb,'"light"'::jsonb,'"dark"'::jsonb) AND e->>'key' IN ('ff76Run','ff76Preview','ff76Download','ff76Share','ffx-hero-new','ffx-hero-reserve','ff51ArchiveRefresh','ff51ArchiveExport','ff51CustomerFind')
      ELSE false END) THEN RETURN false; END IF;
   seen:=array_append(seen,e->>'key');
  END LOOP;
 END LOOP;
 RETURN true;
END $function$;
CREATE OR REPLACE FUNCTION ff_private.a09_merge_elements(p_screen text, p_exact jsonb, p_inherited jsonb, p_patch jsonb, p_kinds text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE spec jsonb:='{"dashboard_status":{"screen":"dashboard","keys":["dashboard_status_tag"],"styleOnly":true},"orders_status":{"screen":"orders","keys":["orders_status_tag","orders_addition_warning"],"styleOnly":true},"driver_status":{"screen":"driver","keys":["driver_offer_countdown","driver_status_tag"],"styleOnly":true},"cashier_status":{"screen":"cashier","keys":["cashier_status_tag","cashier_addition_warning"],"styleOnly":true},"burger_regions":{"screen":"burger_kitchen","keys":["ffBurgerKitchenStatus","ffBurgerKitchenBranch","ffBurgerKitchenActive","ffBurgerKitchenFinished"],"styleOnly":true},"dashboard_regions":{"screen":"dashboard","keys":["ffx-hero-title","ffx-hero-sub","ffx-kpis","ffx-shortcuts","ffx-order-list","ffx-overdue"],"styleOnly":true},"order_fields":{"screen":"orders","keys":["newBranch","ffbQuickInput","newPhone","newArea","newFee","newNotes","newCustomerName","newChannel","newFullAddress","ffbMenuSearch","newItems"],"styleOnly":true},"order_tabs":{"screen":"orders","keys":["ffbTabMenu","ffbTabText"],"styleOnly":false},"order_tools":{"screen":"orders","keys":["ffbApplyText","ffbMenuReload"],"styleOnly":true},"cashier_regions":{"screen":"cashier","keys":["cashierOrders"],"styleOnly":true},"assembly_regions":{"screen":"assembly","keys":["ffV12BranchTitle","ffV12AssemblyStatus","ffV12AssemblySummary","ffV12AssemblyOrders"],"styleOnly":true},"catalog_fields":{"screen":"catalog","keys":["ff51CatName","ff51ItemName","ff51ItemPrice","ff51OfferName","ff51OfferPrice"],"styleOnly":true},"catalog_regions":{"screen":"catalog","keys":["ff51CatalogItems","ff51OffersList"],"styleOnly":true},"customer_fields":{"screen":"customers","keys":["ff51CustomerSearch","ff51CustomerNoteText"],"styleOnly":true},"customer_regions":{"screen":"customers","keys":["ff51CustomersList","ff51CustomerHistory","ff51CustomerNotesList"],"styleOnly":true},"report_fields":{"screen":"reports","keys":["ff76From","ff76To","ff76Branch","ff76Driver","ffA10Staff","ffA10Area","ffA10Item","ffA10Status","ff76Mode","ff76Trend"],"styleOnly":true},"report_regions":{"screen":"reports","keys":["ff76Status","ff76Body","ff76ApprovalBox"],"styleOnly":true},"staff_regions":{"screen":"staff","keys":["staffAdminList","staffAuditList"],"styleOnly":true},"archive_fields":{"screen":"archive","keys":["ff51ArchiveFrom","ff51ArchiveTo","ff51ArchiveStatus","ff51ArchiveBranch"],"styleOnly":true},"archive_regions":{"screen":"archive","keys":["ff51ArchiveCount","ff51ArchiveList"],"styleOnly":true},"ratings_regions":{"screen":"ratings","keys":["ff51RatingBranch","ff51RatingsList"],"styleOnly":true},"reservation_fields":{"screen":"reservations","keys":["ff49ReserveBranch","ff49ReserveName","ff49ReservePhone","ff49ReserveNotes","ff49ReservePickup","ff49ReserveItems"],"styleOnly":true},"reservation_regions":{"screen":"reservations","keys":["ff49ReservationsList"],"styleOnly":true},"case_fields":{"screen":"cases","keys":["ff41Kind","ff41Branch","ff41Priority","ff41Subject","ff41Description","ff41FilterKind","ff41FilterStatus"],"styleOnly":true},"case_regions":{"screen":"cases","keys":["ff41CaseList","ff41Detail"],"styleOnly":true},"message_fields":{"screen":"messages","keys":["ff39Title","ff39Role","ff39Branch","ff39Body"],"styleOnly":true},"message_regions":{"screen":"messages","keys":["ff39InboxList","ff39SentLog"],"styleOnly":true},"system_regions":{"screen":"system","keys":["ff48Summary","ff48Rows","ff47Stats","ff47Cases","ff46Summary","ff44Results","ff43Findings"],"styleOnly":true},"reports_actions":{"screen":"reports","keys":["ff76Run","ff76Preview","ff76Download","ff76Share"]},"dashboard_actions":{"screen":"dashboard","keys":["ffx-hero-new","ffx-hero-reserve","ffx-hero-overdue"]},"orders_actions":{"screen":"orders","keys":["createBtn","ffA06DiscardDraft","ffReserveBottom"]},"driver_actions":{"screen":"driver","keys":["ff51BreakBtn","clockInBtn","clockOutBtn"]},"assembly_actions":{"screen":"assembly","keys":["ffV12Toggle","ffV12Refresh","ffV12BurgerOpen","ffV12Logout"]},"burger_actions":{"screen":"burger_kitchen","keys":["ffBurgerKitchenNotifications","ffBurgerViewFinished","ffBurgerKitchenRefresh","ffBurgerKitchenLogout"]},"catalog_actions":{"screen":"catalog","keys":["ff51ItemSave","ff51ItemReset"]},"catalog_offers":{"screen":"catalog","keys":["ff51OfferSave","ff51OfferReset"]},"archive_actions":{"screen":"archive","keys":["ff51ArchiveRefresh","ff51ArchiveExport","ff51ArchiveClose"]},"ratings_actions":{"screen":"ratings","keys":["ff51RatingsRefresh","ff51RatingsClose"]},"reservations_actions":{"screen":"reservations","keys":["ff49ReservationsRefresh","ff49ReservationsClose"]},"cases_actions":{"screen":"cases","keys":["ff41Refresh","ff41Close"]},"messages_actions":{"screen":"messages","keys":["ff39Refresh","ff39Close"]},"system_actions":{"screen":"system","keys":["ff48Refresh","ff48Export","ff48Close"]},"driver_regions":{"screen":"driver","keys":["clockInBtn","driverOffers","driverTasks"]},"assembly_stats":{"screen":"assembly","keys":["ffV12CountAll","ffV12CountPrinted","ffV12CountPreparing","ffV12CountReady"]},"cashier_stage":{"screen":"cashier","keys":["cashier_stage"]},"staff_actions":{"screen":"staff","keys":["staffAuditRefresh"]},"customers_actions":{"screen":"customers","keys":["ff51CustomerFind","ff51CustomerNoteSave"]},"finance_actions":{"screen":"finance","keys":["ff42Load","ff42Export","ff42ClosePanel","ff42Save","ff42CloseSettlement","ff42ShowDetail"],"styleOnly":true},"finance_fields":{"screen":"finance","keys":["ff42Day","ff42Branch","ff42CashDue","ff42CashReceived","ff42Difference","ff42Notes"],"styleOnly":true},"finance_regions":{"screen":"finance","keys":["ff42Status","ff42Summary","ff42List","ff42Form","ff42Detail"],"styleOnly":true},"branches_actions":{"screen":"branches","keys":["ffA05BranchPolicyBtn","ffA05Close","ffA05SaveHours","ffA05SaveTariff","ffA05PriceHistory"],"styleOnly":true},"branches_fields":{"screen":"branches","keys":["ffA05PolicyBranch","ffA05Effective","ffA05Reason","ffA05Day","ffA05Closed","ffA05Open","ffA05CloseTime","ffA05Shift","ffA05Area","ffA05Tariff"],"styleOnly":true},"branches_regions":{"screen":"branches","keys":["ffA05PolicyStatus","ffA05PolicyCurrent","ffA05PolicyHistory","ffA05PriceRows"],"styleOnly":true},"login_actions":{"screen":"login","keys":["loginBtn","ff61ApplyToggle","ff61StatusToggle","ff71CustomerToggle","ff71CustomerSend","ff71CustomerVerify","ff61ApplySend","ff61TrackSend"],"styleOnly":true},"login_fields":{"screen":"login","keys":["email","password","ff71CustomerPhone","ff71CustomerCode","ff61TrackCode","loginStatus","ff71CustomerMessage"],"styleOnly":true},"join_fields":{"screen":"login","keys":["join_name","join_email","join_phone","join_qualification","join_address","join_age","join_marital","join_role","join_experience","join_message","ff61Consent","ff61ApplyInfo"],"styleOnly":true},"customer_portal_actions":{"screen":"customer_portal","keys":["ff28Refresh","ff28Logout"],"styleOnly":true},"customer_portal_regions":{"screen":"customer_portal","keys":["ff28Title","ff28State","ff28Rows","ff28Name","ff28Role"],"styleOnly":true},"system_qa_controls":{"screen":"system","keys":["ff47Reload","ff47Close","ff47Version","ff47Title","ff47Create","ff47Runs","ff47Export","ff47Finish","ff47Reopen","ff47Category","ff47Filter"],"styleOnly":true},"system_readiness_controls":{"screen":"system","keys":["ff46Run","ff46Export","ff46Close"],"styleOnly":true},"system_access_controls":{"screen":"system","keys":["ff45Run","ff45Export","ff45Close"],"styleOnly":true},"system_integrity_controls":{"screen":"system","keys":["ff44Export","ff44Close","ff44From","ff44To","ff44Run"],"styleOnly":true},"system_security_controls":{"screen":"system","keys":["ff43Run","ff43Export","ff43Close"],"styleOnly":true},"case_contact_controls":{"screen":"cases","keys":["ff41Order","ff41CustomerName","ff41CustomerPhone","ff41Channel","ff41Create"],"styleOnly":true},"message_delivery_controls":{"screen":"messages","keys":["ff39Send","ff39SentRefresh"],"styleOnly":true},"dashboard_alert_controls":{"screen":"dashboard","keys":["ff40AlertRefresh","ff40AlertsClose","ff40AlertBranch"],"styleOnly":true},"staff_filter_controls":{"screen":"staff","keys":["ffEditMyAccount","staffAdminRefresh","ffA05StaffSearch","ffA05StaffRole","ffA05StaffActive","ffA05StaffSort","permissionEmployee","permissionLoad"],"styleOnly":true},"catalog_edit_controls":{"screen":"catalog","keys":["ff51CatalogRefresh","ff51CatalogClose","ffCatalogCardTarget","ffCatalogCardSort","ffCatalogCardStyle","ffCatalogCardSave","ffAliasTarget","ffAliasNames","ffAliasSave","ffAliasDefault"],"styleOnly":true},"customer_close_control":{"screen":"customers","keys":["ff51CustomersClose"],"styleOnly":true},"archive_page_controls":{"screen":"archive","keys":["ff51ArchivePrev","ff51ArchiveNext"],"styleOnly":true},"order_change_controls":{"screen":"orders","keys":["ff50Refresh","ff50Close","ff50RequestItems","ff50RequestReason","ff50RequestSave","ff50RequestCancel"],"styleOnly":true},"order_transfer_controls":{"screen":"orders","keys":["ff49TransferRefresh","ff49TransferClose"],"styleOnly":true},"reservation_save_control":{"screen":"reservations","keys":["ff49ReserveSave"],"styleOnly":true},"assembly_sound_control":{"screen":"assembly","keys":["ff66AssemblySoundSettings"],"styleOnly":true},"staff_edit_controls":{"screen":"staff","keys":["ffEditClose","ffEditSave"],"styleOnly":true}}'::jsonb; g record; old_rows jsonb; new_rows jsonb; out_rows jsonb:=coalesce(p_exact,'{}'); old_order text[]; new_order text[];
BEGIN
 IF NOT ff_private.a07_valid_elements(p_patch,p_screen) THEN RETURN NULL; END IF;
 FOR g IN SELECT * FROM jsonb_each(p_patch) LOOP
  old_rows:=coalesce(p_exact->g.key,p_inherited->g.key);
  IF old_rows IS NULL THEN SELECT jsonb_agg(jsonb_build_object('key',k,'shape','pack','size','normal') ORDER BY ord) INTO old_rows FROM jsonb_array_elements_text(spec->g.key->'keys') WITH ORDINALITY AS a(k,ord);END IF;
  new_rows:=g.value;
  SELECT array_agg(e->>'key' ORDER BY ord) INTO old_order FROM jsonb_array_elements(old_rows) WITH ORDINALITY a(e,ord);
  SELECT array_agg(e->>'key' ORDER BY ord) INTO new_order FROM jsonb_array_elements(new_rows) WITH ORDINALITY a(e,ord);
  IF NOT ('layout'=ANY(p_kinds)) AND old_order IS DISTINCT FROM new_order THEN RETURN NULL; END IF;
  IF NOT ('buttons'=ANY(p_kinds)) AND EXISTS(SELECT FROM jsonb_array_elements(old_rows) a JOIN jsonb_array_elements(new_rows) b ON a->>'key'=b->>'key' WHERE a->>'shape' IS DISTINCT FROM b->>'shape' OR a->>'size' IS DISTINCT FROM b->>'size') THEN RETURN NULL; END IF;
  IF EXISTS(
   SELECT 1 FROM jsonb_array_elements(new_rows) b
   LEFT JOIN LATERAL (SELECT a FROM jsonb_array_elements(coalesce(p_exact->g.key,'[]')) a WHERE a->>'key'=b->>'key') ex ON true
   LEFT JOIN LATERAL (SELECT a FROM jsonb_array_elements(coalesce(p_inherited->g.key,'[]')) a WHERE a->>'key'=b->>'key') inh ON true
   WHERE (b-ARRAY['key','shape','size','orderMode']) IS DISTINCT FROM
     ((coalesce(inh.a,'{}')||coalesce(ex.a,'{}'))-ARRAY['key','shape','size','orderMode'])
  ) THEN RETURN NULL; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(new_rows) b WHERE b ? 'orderMode') AND NOT ('layout'=ANY(p_kinds)) THEN RETURN NULL; END IF;
  SELECT jsonb_agg((b.row-ARRAY['font','weight','spacing','border','shadow','tone','orderMode','icon','hover','press','align','textScale'])||
     (coalesce((SELECT a FROM jsonb_array_elements(coalesce(p_exact->g.key,'[]')) a WHERE a->>'key'=b.row->>'key'),'{}')-ARRAY['key','shape','size','orderMode']) || CASE WHEN NOT ('layout'=ANY(p_kinds)) AND (p_exact->g.key->0->>'orderMode'='inherit' OR p_exact->g.key IS NULL) THEN '{"orderMode":"inherit"}'::jsonb WHEN 'layout'=ANY(p_kinds) AND b.row->>'orderMode'='inherit' THEN '{"orderMode":"inherit"}'::jsonb ELSE '{}'::jsonb END ORDER BY b.ord)
  INTO new_rows FROM jsonb_array_elements(new_rows) WITH ORDINALITY b(row,ord);
  out_rows:=out_rows||jsonb_build_object(g.key,new_rows);
 END LOOP;
 RETURN out_rows;
END $function$;
